import { useState } from "react"

class Underline extends React.Component<{ color: string }> {
    render() {
        return (
            <motion.div
                layoutId="underline"
                initial={false}
                animate={{ backgroundColor: this.props.color }}
                style={{
                    width: "100%",
                    height: "8px",
                    borderRadius: "4px",
                    position: "absolute",
                    bottom: "-4px",
                }}
            />
        )
    }
}

interface ItemProps {
    i: number
    title: string
    selected: number
    color: string
    setSelected: (i: number) => void
}

class Item extends React.Component<ItemProps> {
    render() {
        const { i, title, selected, color, setSelected } = this.props

        return (
            <motion.li
                key={i}
                id={i.toString()}
                layout
                style={{
                    listStyle: "none",
                    padding: 0,
                    margin: 0,
                    userSelect: "none",
                    fontSize: i === selected ? "64px" : "32px",
                    marginLeft: "20px",
                    position: "relative",
                    cursor: "pointer",
                    color: i === selected ? color : "#333",
                }}
                onClick={() => setSelected(i)}
            >
                {i === selected && <Underline color={color} />}
                {title}
            </motion.li>
        )
    }
}

